function detectCurrentSeason(): TrixSeason {
  const m = new Date().getMonth() + 1;
  if (m <= 2 || m === 12) return 'winter';
  if (m <= 5)             return 'spring';
  if (m <= 8)             return 'summer';
  return 'autumn';
}

