// Maps a governorate's exact gov_name_f to the region id used by
// TrixRegionData/TrixPredRegion (see trix.service.ts / trix-prediction.service.ts).
// "Gulf of Tunis" covers the whole Grand Tunis conurbation, not just the
// (tiny) Tunis governorate itself, so Ariana/Ben Arous/Manubah are coloured
// as part of the same region.
const GOV_TO_REGION_ID: Record<string, string> = {
  'Bizerte': 'bizerte',
  'Tunis': 'tunis',
  'Ariana': 'tunis',
  'Ben Arous': 'tunis',
  'Manubah': 'tunis',
  'Gabès': 'gabes',
};

// Area-centroids of the Bizerte/Tunis/Gabès shapes (same viewBox space as
// GOVERNORATE_DEFS), used to place a name label directly on each colored
// governorate — so a viewer unfamiliar with Tunisian geography can still
// tell which shape is which region.
const GOV_LABEL_POS: Record<string, { x: number; y: number }> = {
  'Bizerte': { x: 30.74, y: 8.36 },
  'Tunis':   { x: 38.88, y: 13.26 },
  'Gabès':   { x: 33.27, y: 66.95 },
};

@Component({
  selector: 'app-landing-overview',
  templateUrl: './landing-overview.component.html',
})
export class LandingOverviewComponent implements OnInit, AfterViewInit, OnDestroy {

  trixData: TrixRegionData[] = [];
  trixLoading = true;
  selectedSeason: TrixSeason = detectCurrentSeason();
  useMockData = false;

  predData: TrixPredRegion[] = [];
  predLoading = true;
  predError = false;
  selectedPredSeason: TrixSeason = detectCurrentSeason();

  totalResearchProjects: number | null = null;
  totalPortalProjects: number | null = null;
  activePortalProjects: number | null = null;

  readonly COUNTRIES = COUNTRY_DEFS;
  // All 24 Tunisian governorate boundaries, layered over TUNISIA_PATH so the
  // map is "cut by regions"; only Bizerte/Tunis/Gabès get a TRIX-status fill.
  readonly GOVERNORATES = GOVERNORATE_DEFS;
  readonly GOV_LABEL_POS = GOV_LABEL_POS;

  selectedCountryA: CountryMapDef = COUNTRY_DEFS[0];
  selectedCountryB: CountryMapDef = COUNTRY_DEFS[0];
  showCountryDdA = false;
  showCountryDdB = false;

  toggleCountryDdA(): void { this.showCountryDdA = !this.showCountryDdA; }
  toggleCountryDdB(): void { this.showCountryDdB = !this.showCountryDdB; }

  selectCountryA(c: CountryMapDef): void {
    this.selectedCountryA = c;
    this.showCountryDdA = false;
  }

  selectCountryB(c: CountryMapDef): void {
    this.selectedCountryB = c;
    this.showCountryDdB = false;
  }

  private io?: IntersectionObserver;

  get displayTrixData(): TrixRegionData[] {
    return this.useMockData ? TRIX_MOCK : this.trixData;
  }

  // Bizerte / Tunis / Gabès — canonical display order for the status rows.
  // The prediction API returns regions as [bizerte, gabes, tunis], so it
  // can't be trusted as-is — always re-sort to this order before use.
  private readonly REGION_ORDER = ['bizerte', 'tunis', 'gabes'];

  private sortByCanonicalOrder<T extends { id: string }>(regions: T[]): T[] {
    return [...regions].sort(
      (a, b) => this.REGION_ORDER.indexOf(a.id) - this.REGION_ORDER.indexOf(b.id)
    );
  }

  toggleMockData(): void {
    this.useMockData = !this.useMockData;
  }

  constructor(
    private trixService: TrixService,
    private trixPredService: TrixPredictionService,
    private portalProjectsService: PortalProjectsService,
    private projectService: ProjectService,
    private projectGroupService: ProjectGroupService,
    private destroyRef: DestroyRef,
    private el: ElementRef,
    public themeService: ThemeService,
  ) {}

  ngOnInit(): void {
    this.trixService.getTrixData()
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: data => { this.trixData = this.sortByCanonicalOrder(data); this.trixLoading = false; },
        error: ()   => { this.trixLoading = false; }
      });

    this.trixPredService.getPredictions()
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: data => { this.predData = this.sortByCanonicalOrder(data); this.predLoading = false; },
        error: ()   => { this.predLoading = false; this.predError = true; }
      });

    this.portalProjectsService.list()
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe(projects => {
        this.totalPortalProjects = projects.length;
        this.activePortalProjects = projects.filter(p => p.isActive).length;
      });

    this.projectService.getAllProjects().subscribe({
      next: p => { this.totalResearchProjects = p.length; },
      error: () => {}
    });
  }

  ngAfterViewInit(): void {
    this.observeFade();
  }

  ngOnDestroy(): void {
    this.io?.disconnect();
  }

  getSeasonResult(region: TrixRegionData): TrixResult {
    return region.seasons[this.selectedSeason];
  }

  getTrixColor(trix: number | null): string {
    const light = this.themeService.isLight;
    if (trix === null) return light ? '#9bb0bc' : '#5d7785';
    if (trix <= 4)  return light ? '#1a8f7f' : '#4ad6c4';
    if (trix <= 5)  return light ? '#b36c00' : '#f5b94a';
    if (trix <= 6)  return light ? '#c2580a' : '#f97316';
    return                light ? '#dc2626' : '#ef4444';
  }

  getPredResult(region: TrixPredRegion): TrixPredResult {
    return region.seasons[this.selectedPredSeason];
  }

  isHighlightedGovernorate(name: string): boolean {
    return !!GOV_TO_REGION_ID[name];
  }

  getGovernorateFill(name: string, forPredicted: boolean): string {
    const regionId = GOV_TO_REGION_ID[name];
    if (!regionId) return 'none';
    if (forPredicted) {
      const region = this.predData.find(r => r.id === regionId);
      return this.getTrixColor(region ? this.getPredResult(region).trix : null);
    }
    const region = this.displayTrixData.find(r => r.id === regionId);
    return this.getTrixColor(region ? this.getSeasonResult(region).trix : null);
  }

  getNeedlePoints(trix: number | null): string {
    const t = trix ?? 0;
    const angle = (135 + (t / 10) * 270) * Math.PI / 180;
    const c = Math.cos(angle);
    const s = Math.sin(angle);
    const tipX = 100 + 65 * c,  tipY = 100 + 65 * s;
    const bx   = 100 -  9 * c,  by   = 100 -  9 * s;
    return [
      `${tipX.toFixed(2)},${tipY.toFixed(2)}`,
      `${(bx - 6 * s).toFixed(2)},${(by + 6 * c).toFixed(2)}`,
      `${(bx + 6 * s).toFixed(2)},${(by - 6 * c).toFixed(2)}`,
    ].join(' ');
  }

  @HostListener('document:click', ['$event'])
  onDocumentClick(event: Event): void {
    const target = event.target as HTMLElement;
    if (!target.closest('.trix-country-wrap-a')) this.showCountryDdA = false;
    if (!target.closest('.trix-country-wrap-b')) this.showCountryDdB = false;
  }

  private observeFade(): void {
    this.io?.disconnect();
    this.io = new IntersectionObserver(
      (entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            (entry.target as HTMLElement).classList.add('in');
            this.io?.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.08, rootMargin: '0px 0px -40px 0px' }
    );
    this.el.nativeElement.querySelectorAll('.fade-up:not(.in)')
      .forEach((e: Element) => this.io!.observe(e));
  }
}
